WITH metrics AS (SELECT *, AVG(sqft) OVER (PARTITION BY city ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_sqft, COUNT(sqft) OVER (PARTITION BY city ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_sqft, MIN(sqft) OVER (PARTITION BY city ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_sqft FROM stores) SELECT id, opened_date, sqft, running_avg_sqft, running_count_sqft FROM metrics ORDER BY running_count_sqft DESC NULLS FIRST
